package com.estoqueinteligente.product;
import java.util.*;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface ProductRepository extends JpaRepository<Product,Long>{@Query("SELECT p FROM Product p JOIN FETCH p.category LEFT JOIN FETCH p.supplier ORDER BY p.name")List<Product> findAllWithCategory();@Query("SELECT p FROM Product p JOIN FETCH p.category LEFT JOIN FETCH p.supplier WHERE p.id=:id")Optional<Product> findByIdWithCategory(@Param("id")Long id);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("SELECT p FROM Product p JOIN FETCH p.category LEFT JOIN FETCH p.supplier WHERE p.id=:id")Optional<Product> findByIdForUpdate(@Param("id")Long id);boolean existsByBarcode(String barcode);boolean existsByBarcodeAndIdNot(String barcode,Long id);}
